"""Parse version strings like "1.2.3" or "1.2.3-beta.2"."""


def parse(version: str) -> dict:
    parts = version.split(".")
    major_s, minor_s, patch_s = parts[:3]
    pre = ""
    if len(parts) > 3:
        pre = ".".join(parts[3:])
    return {"major": int(major_s), "minor": int(minor_s),
            "patch": int(patch_s), "pre": pre}

"""Parse version strings like "1.2.3" or "1.2.3-beta.2"."""


def parse(version: str) -> dict:
    parts = version.split("-")
    base = parts[0].split(".")
    pre = parts[1] if len(parts) > 1 else ""
    return {"major": int(base[0]), "minor": int(base[1]),
            "patch": int(base[2]), "pre": pre}
